import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>
#include <cstdint>

// Implicit GEMM restructuring: view the convolution as C[M, C_out] = A[M, Kk] * W[C_out, Kk]^T,
// where M flattens (batch, out_h, out_w) and Kk flattens (in_c, kh, kw). Each CTA keeps the
// small C_out dimension inside the block and tiles the large M dimension, staging on-the-fly
// im2col A tiles and weight B tiles in shared memory with register-blocked accumulation.
constexpr int BM = 64;
constexpr int BN = 128;
constexpr int BK = 16;
constexpr int TM = 4;
constexpr int TN = 8;
constexpr int THREADS = 256;
__global__ void conv2d_forward_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C_in, int H, int W,
    int C_out, int H_out, int W_out,
    int K, int stride, int pad, int dil)
{
    const int m0  = blockIdx.x * BM;
    const int oc0 = blockIdx.y * BN;
    const int tid = threadIdx.y * blockDim.x + threadIdx.x;
    const int tx  = threadIdx.x;
    const int ty  = threadIdx.y;
    const int64_t M_total = (int64_t)N * H_out * W_out;
    const int Kk = C_in * K * K;
    const int kk_sq = K * K;
    __shared__ float sA[BM][BK];
    __shared__ float sB[BK][BN];
    // Per-row metadata for the 64 flattened output positions owned by this CTA.
    __shared__ int64_t s_row_base[BM];
    __shared__ int s_ih0[BM];
    __shared__ int s_iw0[BM];
    __shared__ unsigned char s_row_valid[BM];
    __shared__ int64_t s_row_out[BM];
    // Per-k metadata for the current BK slice of (ic, kh, kw).
    __shared__ int64_t s_kadd[BK];
    __shared__ int s_khd[BK];
    __shared__ int s_kwd[BK];
    if (tid < BM) {
        const int64_t m = (int64_t)m0 + tid;
        unsigned char valid = 0;
        int64_t base = 0, out_off = 0;
        int ih0 = 0, iw0 = 0;
        if (m < M_total) {
            const int ow = (int)(m % W_out);
            const int64_t t = m / W_out;
            const int oh = (int)(t % H_out);
            const int n  = (int)(t / H_out);
            ih0 = oh * stride - pad;
            iw0 = ow * stride - pad;
            base = (int64_t)n * C_in * H * W + (int64_t)ih0 * W + iw0;
            out_off = (int64_t)n * C_out * H_out * W_out + (int64_t)oh * W_out + ow;
            valid = 1;
        }
        s_row_base[tid] = base;
        s_row_out[tid] = out_off;
        s_ih0[tid] = ih0;
        s_iw0[tid] = iw0;
        s_row_valid[tid] = valid;
    }
    float acc[TM][TN];
    #pragma unroll
    for (int i = 0; i < TM; ++i)
        #pragma unroll
        for (int j = 0; j < TN; ++j)
            acc[i][j] = 0.0f;
    const int ktiles = (Kk + BK - 1) / BK;
    for (int kt = 0; kt < ktiles; ++kt) {
        const int k0 = kt * BK;
        if (tid < BK) {
            const int k = k0 + tid;
            int64_t add = 0;
            int khd = 0, kwd = 0;
            if (k < Kk) {
                const int ic  = k / kk_sq;
                const int rem = k - ic * kk_sq;
                const int kh  = rem / K;
                const int kw  = rem - kh * K;
                khd = kh * dil;
                kwd = kw * dil;
                add = (int64_t)ic * H * W + (int64_t)khd * W + kwd;
            }
            s_kadd[tid] = add;
            s_khd[tid] = khd;
            s_kwd[tid] = kwd;
        }
        __syncthreads();
        // Stage the on-the-fly im2col A tile as BK x BM.
        #pragma unroll
        for (int l = 0; l < (BM * BK) / THREADS; ++l) {
            const int idx = tid + l * THREADS;
            const int mm = idx / BK;
            const int kk = idx - mm * BK;
            float v = 0.0f;
            if (s_row_valid[mm] && (k0 + kk) < Kk) {
                const int ih = s_ih0[mm] + s_khd[kk];
                const int iw = s_iw0[mm] + s_kwd[kk];
                if (ih >= 0 && ih < H && iw >= 0 && iw < W)
                    v = input[s_row_base[mm] + s_kadd[kk]];
            }
            sA[mm][kk] = v;
        }
        // Stage the B tile as BK x BN from row-major weights [C_out, Kk].
        #pragma unroll
        for (int l = 0; l < (BK * BN) / THREADS; ++l) {
            const int idx = tid + l * THREADS;
            const int nn = idx / BK;
            const int kk = idx - nn * BK;
            const int oc = oc0 + nn;
            const int k = k0 + kk;
            float v = 0.0f;
            if (oc < C_out && k < Kk)
                v = weight[(int64_t)oc * Kk + k];
            sB[kk][nn] = v;
        }
        __syncthreads();
        #pragma unroll
        for (int kk = 0; kk < BK; ++kk) {
            float av[TM];
            float bv[TN];
            #pragma unroll
            for (int i = 0; i < TM; ++i)
                av[i] = sA[ty + i * 16][kk];
            #pragma unroll
            for (int j = 0; j < TN; ++j)
                bv[j] = sB[kk][tx + j * 16];
            #pragma unroll
            for (int i = 0; i < TM; ++i)
                #pragma unroll
                for (int j = 0; j < TN; ++j)
                    acc[i][j] += av[i] * bv[j];
        }
        __syncthreads();
    }
    #pragma unroll
    for (int i = 0; i < TM; ++i) {
        const int m_local = ty + i * 16;
        const int64_t row = (int64_t)m0 + m_local;
        #pragma unroll
        for (int j = 0; j < TN; ++j) {
            const int col = oc0 + tx + j * 16;
            if (row < M_total && col < C_out) {
                const float b = (bias != nullptr) ? bias[col] : 0.0f;
                output[s_row_out[m_local] + (int64_t)col * H_out * W_out] = acc[i][j] + b;
            }
        }
    }
}
torch::Tensor conv2d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int64_t stride, int64_t pad, int64_t dil)
{
    TORCH_CHECK(input.is_cuda() && weight.is_cuda(), "input and weight must be CUDA tensors");
    TORCH_CHECK(input.scalar_type() == torch::kFloat32, "only float32 supported");
    auto input_c  = input.contiguous();
    auto weight_c = weight.contiguous();
    const int N     = input_c.size(0);
    const int C_in  = input_c.size(1);
    const int H     = input_c.size(2);
    const int W     = input_c.size(3);
    const int C_out = weight_c.size(0);
    const int K     = weight_c.size(2);
    const int H_out = (H + 2 * (int)pad - (int)dil * (K - 1) - 1) / (int)stride + 1;
    const int W_out = (W + 2 * (int)pad - (int)dil * (K - 1) - 1) / (int)stride + 1;
    auto output = torch::empty({N, C_out, H_out, W_out}, input_c.options());
    const int64_t M_total = (int64_t)N * H_out * W_out;
    if (M_total == 0 || C_out == 0)
        return output;
    dim3 block(16, 16);
    dim3 grid((unsigned int)((M_total + BM - 1) / BM),
              (unsigned int)((C_out + BN - 1) / BN), 1);
    torch::Tensor bias_c;
    const float* bias_ptr = nullptr;
    if (bias.has_value() && bias->defined()) {
        bias_c = bias->contiguous();
        bias_ptr = bias_c.data_ptr<float>();
    }
    conv2d_forward_kernel<<<grid, block, 0, at::cuda::getCurrentCUDAStream()>>>(
        input_c.data_ptr<float>(),
        weight_c.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        N, C_in, H, W,
        C_out, H_out, W_out,
        K, (int)stride, (int)pad, (int)dil);
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return output;
}
"""

cpp_src = r"""
#include <torch/extension.h>
torch::Tensor conv2d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int64_t stride, int64_t pad, int64_t dil);
"""

_ext = load_inline(
    name="conv2d_tiled_ext",
    cpp_sources=cpp_src,
    cuda_sources=cuda_src,
    functions=["conv2d_forward"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    2D convolution backed by a single custom CUDA kernel (tiled direct conv
    with shared-memory staging of weights and input halo tiles).
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1,
                 groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        assert groups == 1, "custom kernel supports groups == 1"
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.conv2d = nn.Conv2d(in_channels, out_channels, (kernel_size, kernel_size),
                                stride=stride, padding=padding, dilation=dilation,
                                groups=groups, bias=bias)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not x.is_cuda:
            raise RuntimeError("ModelNew requires CUDA input")
        return _ext.conv2d_forward(
            x, self.conv2d.weight, self.conv2d.bias,
            self.stride, self.padding, self.dilation)

